void ModernDial::paint(juce::Graphics&g){auto b=getLocalBounds().toFloat();float scale=juce::jmin(b.getWidth()/180.f,b.getHeight()/220.f),r=juce::jmin(b.getWidth()*.39f,b.getHeight()*.32f);auto c=juce::Point<float>(b.getCentreX(),b.getY()+r+16*scale);g.setColour(juce::Colours::black.withAlpha(.48f));g.fillEllipse(c.x-r-7*scale,c.y-r+7*scale,2*r+14*scale,2*r+14*scale);juce::ColourGradient face(juce::Colour(0xff18263a),c.x-r,c.y-r,juce::Colour(0xff08111d),c.x+r,c.y+r,false);g.setGradientFill(face);g.fillEllipse(c.x-r,c.y-r,2*r,2*r);g.setColour(juce::Colour(0xff263a55));g.drawEllipse(c.x-r,c.y-r,2*r,2*r,1.2f*scale);float start=juce::MathConstants<float>::pi*1.25f,end=juce::MathConstants<float>::pi*2.75f,p=(float)valueToProportionOfLength(getValue());juce::Path track,arc;track.addCentredArc(c.x,c.y,r+8*scale,r+8*scale,0,start,end,true);g.setColour(juce::Colour(0xff111a27));g.strokePath(track,juce::PathStrokeType(7*scale,juce::PathStrokeType::curved,juce::PathStrokeType::rounded));if(p>0){arc.addCentredArc(c.x,c.y,r+8*scale,r+8*scale,0,start,start+(end-start)*p,true);juce::ColourGradient glow(accent.brighter(.3f),c.x-r,c.y,accent,c.x+r,c.y,false);g.setGradientFill(glow);g.strokePath(arc,juce::PathStrokeType(7*scale,juce::PathStrokeType::curved,juce::PathStrokeType::rounded));}float a=start+(end-start)*p;auto thumb=juce::Point<float>(c.x+(r+8*scale)*std::cos(a),c.y+(r+8*scale)*std::sin(a));g.setColour(juce::Colour(0xffdce8ff));g.fillEllipse(thumb.x-6*scale,thumb.y-6*scale,12*scale,12*scale);g.setColour(accent);g.drawEllipse(thumb.x-6*scale,thumb.y-6*scale,12*scale,12*scale,1.5f*scale);label(g,title,{c.x-r,c.y-r*.55f,2*r,24*scale},16*scale,text1(),juce::Justification::centred);label(g,subtitle,{c.x-r,c.y-r*.25f,2*r,20*scale},12*scale,text2(),juce::Justification::centred);juce::String value=infinityAtMaximum&&p>.9995f?juce::String::fromUTF8("∞"):juce::String(getValue(),getInterval()<1?1:0);label(g,value,{c.x-r,c.y-3*scale,2*r,47*scale},34*scale,text1(),juce::Justification::centred);if(!(infinityAtMaximum&&p>.9995f))label(g,unit,{c.x-r,c.y+39*scale,2*r,18*scale},12*scale,text2(),juce::Justification::centred);if(hasKeyboardFocus(false)){g.setColour(accent.withAlpha(.8f));g.drawEllipse(c.x-r-3,c.y-r-3,2*r+6,2*r+6,1.5f);}}
