void PhasePocketAudioProcessorEditor::drawPanel(juce::Graphics&g,juce::Rectangle<float>r,float radius){g.setColour(juce::Colours::black.withAlpha(.45f));g.fillRoundedRectangle(r.translated(0,7),radius);juce::ColourGradient gr(juce::Colour(0xff111d2c),r.getX(),r.getY(),juce::Colour(0xff09121e),r.getRight(),r.getBottom(),false);g.setGradientFill(gr);g.fillRoundedRectangle(r,radius);g.setColour(juce::Colour(0xff29384d));g.drawRoundedRectangle(r,radius,1);g.setColour(juce::Colours::white.withAlpha(.04f));g.drawRoundedRectangle(r.reduced(1),radius-1,1);}
void PhasePocketAudioProcessorEditor::drawSpectrum(juce::Graphics&g,juce::Rectangle<float>r){g.setColour(juce::Colour(0xff050b13));g.fillRoundedRectangle(r,9);for(int i=0;i<=4;++i){g.setColour(juce::Colour(0xff243246).withAlpha(.65f));g.drawHorizontalLine((int)(r.getY()+i*r.getHeight()/4),r.getX(),r.getRight());g.drawVerticalLine((int)(r.getX()+i*r.getWidth()/4),r.getY(),r.getBottom());}auto y=[&](float gain){return r.getY()+r.getHeight()*(1-std::pow(juce::jlimit(0.f,1.f,gain),.25f));};for(int side=1;side>=0;--side){const auto&v=side?spectrumCurve.side:spectrumCurve.mid;juce::Path p,fill;for(int i=0;i<32;++i){float x=r.getX()+r.getWidth()*i/31.f,yy=y(v[i]);if(i==0){p.startNewSubPath(x,yy);fill.startNewSubPath(x,r.getBottom());fill.lineTo(x,yy);}else{p.lineTo(x,yy);fill.lineTo(x,yy);}}fill.lineTo(r.getRight(),r.getBottom());fill.closeSubPath();auto c=side?juce::Colour(0xff25d8d0):juce::Colour(0xff6384ff);g.setGradientFill(juce::ColourGradient(c.withAlpha(.23f),0,r.getY(),c.withAlpha(0.f),0,r.getBottom(),false));g.fillPath(fill);g.setColour(c);g.strokePath(p,juce::PathStrokeType(1.6f));}}
void PhasePocketAudioProcessorEditor::drawScope(juce::Graphics&g,juce::Rectangle<float>r){g.setColour(juce::Colour(0xff050b13));g.fillRoundedRectangle(r,9);g.setColour(juce::Colour(0xff26364c));g.drawHorizontalLine((int)r.getCentreY(),r.getX(),r.getRight());if(!filled)return;double now=history[(size_t)((cursor+4095)%4096)].time;for(int kind=0;kind<2;++kind){g.setColour(kind?juce::Colour(0xffdbe5ff):juce::Colour(0xff2383d9).withAlpha(.75f));for(int i=0;i<filled;++i){auto&v=history[(size_t)((cursor-filled+i+4096)%4096)];double age=now-v.time;if(age<0||age>1)continue;float x=r.getRight()-(float)age*r.getWidth(),lo=kind?v.keyLo:v.outLo,hi=kind?v.keyHi:v.outHi;g.drawLine(x,r.getCentreY()-juce::jlimit(-1.f,1.f,hi)*r.getHeight()*.48f,x,r.getCentreY()-juce::jlimit(-1.f,1.f,lo)*r.getHeight()*.48f,kind?1.2f:.8f);}}}
void PhasePocketAudioProcessorEditor::paint(juce::Graphics&g){g.fillAll(bg());float s=getWidth()/1200.f;juce::Graphics::ScopedSaveState save(g);g.addTransform(juce::AffineTransform::scale(s));juce::ColourGradient halo(juce::Colour(0xff16243a),600,0,bg(),600,700,true);g.setGradientFill(halo);g.fillRect(0,0,1200,896);g.setColour(juce::Colour(0xff28384d).withAlpha(.45f));for(int i=0;i<8;++i){juce::Path p;p.startNewSubPath(420+i*25,0);p.cubicTo(500+i*22,80,470+i*30,125,610+i*36,165);g.strokePath(p,juce::PathStrokeType(1));}label(g,"Phase Pocket",{115,24,360,48},38,text1());label(g,"R  A  I  N  L  I  N  E",{118,72,300,20},13,text2());g.setColour(juce::Colour(0xff4f7cff));for(int i=0;i<5;++i)g.fillRoundedRectangle(42+i*11,45-std::abs(2-i)*7.f,5.f,20+std::abs(2-std::abs(2-i))*13.f,2.5f);drawPanel(g,{25,120,750,540});drawPanel(g,{790,120,385,540});drawPanel(g,{25,680,1150,185});label(g,"Spectral reduction",{50,142,350,30},22,text1());label(g,"M",{690,143,25,28},16,juce::Colour(0xff6384ff),juce::Justification::centred);label(g,"S",{720,143,25,28},16,juce::Colour(0xff25d8d0),juce::Justification::centred);drawSpectrum(g,{100,185,640,190});label(g,"0 dB",{47,178,52,22},14,text2());label(g,"-inf",{55,352,40,22},14,text2());label(g,"20",{92,380,45,20},13,text2());label(g,"20k",{705,380,40,20},13,text2(),juce::Justification::centredRight);label(g,"Oscilloscope",{50,408,350,30},22,text1());drawScope(g,{50,450,690,170});label(g,"-1 s",{50,625,50,20},13,text2());label(g,"Now",{690,625,50,20},13,text2(),juce::Justification::centredRight);label(g,"Sidechain filter",{50,696,170,28},19,text1());label(g,"Low cut",{55,728,85,28},14,text2());label(g,"High cut",{565,728,85,28},14,text2());label(g,"M / S focus",{50,804,95,28},14,text2());label(g,"v0.6.0",{1085,825,65,24},14,text2(),juce::Justification::centredRight);if(bypassLook){g.setColour(juce::Colours::black.withAlpha(.42f));g.fillRect(0,105,1200,791);}}
void PhasePocketAudioProcessorEditor::timerCallback(){PocketTrace t;while(processor.popTrace(t))if(std::isfinite(t.time)){history[(size_t)cursor]=t;cursor=(cursor+1)%4096;filled=juce::jmin(filled+1,4096);}SpectrumTrace c;while(processor.popSpectrum(c))spectrumCurve=c;bool amp=processor.parameters.getRawParameterValue("mode")->load()>.5f;amplitude.setToggleState(amp,juce::dontSendNotification);spectrum.setToggleState(!amp,juce::dontSendNotification);bypassLook=processor.parameters.getRawParameterValue("bypass")->load()>.5f||processor.displayBypass.load();repaint();}
